    "sim.explain.feed_milk_pos": "Adding {feed} kg of feed increases daily feed cost by ₹{feedCost}, but predicted milk yield increases by +{milk} L/day, generating +₹{rev} in additional revenue. The milk revenue exceeds the feed cost, yielding an estimated net benefit of +₹{net}/day.",
    "sim.explain.feed_milk_neg": "Adding {feed} kg of feed increases daily feed cost by ₹{feedCost}, but the model predicts only +{milk} L/day additional milk, worth +₹{rev}/day at ₹{price}/L. The additional feed cost exceeds the milk revenue, resulting in an estimated net impact of -₹{net}/day.",
    "sim.explain.feed_milk_even": "Adding {feed} kg of feed costs +₹{feedCost}/day, which closely balances the predicted +{milk} L/day milk revenue (+₹{rev}/day), resulting in a near break-even impact.",
    "sim.explain.feed_inc_milk_drop": "Increasing feed by {feed} kg adds +₹{feedCost}/day in feed cost, but predicted milk production falls by {milk} L/day (-₹{rev} revenue). The combined effect produces an estimated net impact of -₹{net}/day.",
    "sim.explain.feed_inc_milk_same": "Increasing feed by {feed} kg adds +₹{feedCost}/day in feed cost, while predicted milk yield remains unchanged (₹0.00 revenue change). This results in a net daily cost of -₹{net}/day.",
    "sim.explain.no_feed_milk_pos": "With feed intake unchanged (₹0.00 feed cost delta), environmental or cooling adjustments boost predicted milk yield by +{milk} L/day, producing a net financial gain of +₹{net}/day.",
    "sim.explain.no_feed_milk_neg": "With feed intake unchanged (₹0.00 feed cost delta), environmental stress reduces predicted milk production by {milk} L/day, producing an estimated revenue loss of -₹{net}/day.",
    "sim.explain.no_change": "No change in feed intake or predicted milk yield results in a ₹0.00 net financial impact.",
    "sim.explain.feed_dec_milk_pos": "Reducing feed by {feed} kg saves ₹{feedCost}/day in feed cost while predicted milk yield changes by +{milk} L/day (+₹{rev}/day revenue), yielding a net financial benefit of +₹{net}/day.",
    "sim.explain.feed_dec_milk_neg_save": "Reducing feed by {feed} kg saves ₹{feedCost}/day in feed cost, which outweighs the revenue lost (-₹{rev}/day) from a {milk} L/day decline in milk yield, creating a net savings of +₹{net}/day.",
    "sim.explain.feed_dec_milk_neg_loss": "Reducing feed by {feed} kg saves ₹{feedCost}/day in feed cost, but milk production drops by {milk} L/day (-₹{rev}/day revenue), causing an estimated net loss of -₹{net}/day.",
