    "rec.toast.cow_completed": "गाय के लिए सभी सिफारिशें पूर्ण चिह्नित की गईं।",
    "rec.toast.cow_complete_error": "सभी सिफारिशों को पूर्ण चिह्नित करने में असमर्थ।",
