    "sim.explain.feed_milk_pos": "{feed} किग्रा चारा बढ़ाने से दैनिक चारा लागत ₹{feedCost} बढ़ती है, लेकिन अनुमानित दूध उपज +{milk} लीटर/दिन बढ़ती है, जिससे +₹{rev} अतिरिक्त राजस्व प्राप्त होता है। दूध का राजस्व चारा लागत से अधिक है, जिससे +₹{net}/दिन का अनुमानित शुद्ध लाभ मिलता है।",
    "sim.explain.feed_milk_neg": "{feed} किग्रा चारा बढ़ाने से दैनिक चारा लागत ₹{feedCost} बढ़ती है, लेकिन मॉडल केवल +{milk} लीटर/दिन अतिरिक्त दूध का अनुमान लगाता है, जिसका मूल्य ₹{price}/लीटर पर +₹{rev}/दिन है। अतिरिक्त चारा लागत दूध राजस्व से अधिक है, जिसके परिणामस्वरूप -₹{net}/दिन का अनुमानित शुद्ध प्रभाव पड़ता है।",
    "sim.explain.feed_milk_even": "{feed} किग्रा चारा जोड़ने पर +₹{feedCost}/दिन की लागत आती है, जो अनुमानित +{milk} लीटर/दिन दूध राजस्व (+₹{rev}/दिन) को संतुलित करती है, जिससे लगभग सम-स्तर प्रभाव पड़ता है।",
    "sim.explain.feed_inc_milk_drop": "चारा {feed} किग्रा बढ़ाने से चारा लागत में +₹{feedCost}/दिन जुड़ते हैं, लेकिन अनुमानित दूध उत्पादन {milk} लीटर/दिन (-₹{rev} राजस्व) गिर जाता है। संयुक्त प्रभाव से -₹{net}/दिन का अनुमानित शुद्ध नुकसान होता है।",
    "sim.explain.feed_inc_milk_same": "चारा {feed} किग्रा बढ़ाने से चारा लागत में +₹{feedCost}/दिन जुड़ते हैं, जबकि अनुमानित दूध उपज अपरिवर्तित रहती है (₹0.00 राजस्व परिवर्तन)। इसका परिणाम -₹{net}/दिन की शुद्ध दैनिक लागत है।",
    "sim.explain.no_feed_milk_pos": "चारा सेवन अपरिवर्तित रहने पर (₹0.00 चारा लागत अंतर), पर्यावरणीय या शीतलन समायोजन अनुमानित दूध उपज को +{milk} लीटर/दिन बढ़ाते हैं, जिससे +₹{net}/दिन का शुद्ध वित्तीय लाभ होता है।",
    "sim.explain.no_feed_milk_neg": "चारा सेवन अपरिवर्तित रहने पर (₹0.00 चारा लागत अंतर), पर्यावरणीय तनाव अनुमानित दूध उत्पादन को {milk} लीटर/दिन कम कर देता है, जिससे -₹{net}/दिन का अनुमानित राजस्व नुकसान होता है।",
    "sim.explain.no_change": "चारे के सेवन या अनुमानित दूध उपज में कोई बदलाव न होने से ₹0.00 का शुद्ध वित्तीय प्रभाव पड़ता है।",
    "sim.explain.feed_dec_milk_pos": "चारा {feed} किग्रा घटाने से चारा लागत में ₹{feedCost}/दिन की बचत होती है जबकि अनुमानित दूध उपज में +{milk} लीटर/दिन (+₹{rev}/दिन राजस्व) का बदलाव होता है, जिससे +₹{net}/दिन का शुद्ध वित्तीय लाभ मिलता है।",
    "sim.explain.feed_dec_milk_neg_save": "चारा {feed} किग्रा घटाने से चारा लागत में ₹{feedCost}/दिन की बचत होती है, जो दूध उपज में {milk} लीटर/दिन की गिरावट से हुए नुकसान (-₹{rev}/दिन) से अधिक है, जिससे +₹{net}/दिन की शुद्ध बचत होती है।",
    "sim.explain.feed_dec_milk_neg_loss": "चारा {feed} किग्रा घटाने से चारा लागत में ₹{feedCost}/दिन की बचत होती है, लेकिन दूध उत्पादन {milk} लीटर/दिन (-₹{rev}/दिन राजस्व) गिर जाता है, जिससे -₹{net}/दिन का अनुमानित शुद्ध नुकसान होता है।",
