    "sim.explain.feed_milk_even": "{feed} किलो खाद्य वाढवल्याने +₹{feedCost}/दिवस खर्च येतो, जो अंदाजित +{milk} लिटर/दिवस दूध महसुलाशी (+₹{rev}/दिवस) जवळजवळ समतोल साधतो, परिणामी जवळपास नफा-तोटा समतोल राहतो.",
    "sim.explain.feed_inc_milk_drop": "खाद्य {feed} किलोने वाढवल्याने खाद्याच्या खर्चात +₹{feedCost}/दिवस भर पडते, परंतु अंदाजित दूध उत्पादन {milk} लिटर/दिवस (-₹{rev} महसूल) घटते. एकत्रित परिणामामुळे -₹{net}/दिवस अंदाजित निव्वळ तोटा होतो.",
    "sim.explain.feed_inc_milk_same": "खाद्य {feed} किलोने वाढवल्याने खाद्याच्या खर्चात +₹{feedCost}/दिवस भर पडते, तर अंदाजित दूध उत्पादन अपरिवर्तित राहते (₹०.०० महसूल बदल). याचा परिणाम -₹{net}/दिवस निव्वळ दैनंदिन खर्चात होतो.",
    "sim.explain.no_feed_milk_pos": "खाद्य सेवन अपरिवर्तित असताना (₹०.०० खाद्य खर्च बदल), पर्यावरणीय किंवा शीतलक समायोजनांमुळे अंदाजित दूध उत्पादनात +{milk} लिटर/दिवस वाढ होते, ज्यामुळे +₹{net}/दिवस निव्वळ आर्थिक फायदा होतो.",
    "sim.explain.no_feed_milk_neg": "खाद्य सेवन अपरिवर्तित असताना (₹०.०० खाद्य खर्च बदल), पर्यावरणीय ताणामुळे अंदाजित दूध उत्पादन {milk} लिटर/दिवस कमी होते, ज्यामुळे -₹{net}/दिवस अंदाजित महसूल नुकसान होते.",
    "sim.explain.no_change": "खाद्य सेवन किंवा अंदाजित दूध उत्पादनात कोणताही बदल न झाल्याने निव्वळ आर्थिक प्रभाव ₹०.०० राहतो.",
    "sim.explain.feed_dec_milk_pos": "खाद्य {feed} किलोने कमी केल्याने खाद्याच्या खर्चात ₹{feedCost}/दिवस बचत होते आणि अंदाजित दूध उत्पादनात +{milk} लिटर/दिवस बदल होतो (+₹{rev}/दिवस महसूल), परिणामी +₹{net}/दिवस निव्वळ आर्थिक नफा मिळतो.",
    "sim.explain.feed_dec_milk_neg_save": "खाद्य {feed} किलोने कमी केल्याने खाद्याच्या खर्चात ₹{feedCost}/दिवस बचत होते, जी दूध उत्पादनातील {milk} लिटर/दिवस घसरणीमुळे झालेल्या नुकसानीपेक्षा (-₹{rev}/दिवस) जास्त आहे, परिणामी +₹{net}/दिवस निव्वळ बचत होते.",
    "sim.explain.feed_dec_milk_neg_loss": "खाद्य {feed} किलोने कमी केल्याने खाद्याच्या खर्चात ₹{feedCost}/दिवस बचत होते, परंतु दूध उत्पादन {milk} लिटर/दिवस (-₹{rev}/दिवस महसूल) घटते, ज्यामुळे -₹{net}/दिवस अंदाजित निव्वळ तोटा होतो.",
