    "rec.desc.adjust_feeding_nutrition": "ਖੁਰਾਕ ਦੀ ਖਪਤ ਦਾ ਮੁਲਾਂਕਣ ਕਰੋ ਅਤੇ ਝੁੰਡ ਲਈ ਵਧੇਰੇ ਪੌਸ਼ਟਿਕ ਖੁਰਾਕ ਬਾਰੇ ਵਿਚਾਰ ਕਰੋ।",
    "rec.desc.inspect_feed_bunk": "ਖੁਰਾਕ ਖਰਾਬ ਹੋਣ, ਉੱਲੀ ਜਾਂ ਖੁਰਲੀ ਵਿੱਚ ਮੁਕਾਬਲੇ ਦੀ ਜਾਂਚ ਕਰੋ।",
    "rec.desc.prioritize_heat_mitigation": "ਤਣਾਅ ਘਟਾਉਣ ਲਈ ਕੂਲਿੰਗ, ਹਵਾਦਾਰੀ ਅਤੇ ਜਲ ਸੰਤੁਲਨ 'ਤੇ ਧਿਆਨ ਦਿਓ।",
    "rec.desc.continue_monitoring": "ਕੋਈ ਤੁਰੰਤ ਸਿਫਾਰਸ਼ ਨਹੀਂ ਮਿਲੀ। ਖੁਰਾਕ, ਮੌਸਮ ਅਤੇ ਦੁੱਧ ਦੇ ਰੁਝਾਨਾਂ 'ਤੇ ਨਜ਼ਰ ਰੱਖੋ।",
    "rec.desc.standard_protocols": "ਮਿਆਰੀ ਝੁੰਡ ਸਿਹਤ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰੋ।",
    "rec.why.all_normal": "ਸਾਰੇ ਦਰਜ ਸਿਹਤ, ਤਾਪਮਾਨ, ਮੌਸਮ ਅਤੇ ਦੁੱਧ ਉਤਪਾਦਨ ਦੇ ਮਾਪ ਆਮ ਸੀਮਾ ਦੇ ਅੰਦਰ ਹਨ।",
    "rec.why.unusual_feed": "ਗਾਂ ਦੀ ਹਾਲੀਆ ਖੁਰਾਕ ਖਪਤ ਇਸਦੇ ਆਮ ਪੈਟਰਨ ਨਾਲੋਂ ਕਾਫ਼ੀ ਵੱਖਰੀ ਹੈ। ਖੁਰਾਕ ਵਿੱਚ ਤਬਦੀਲੀ ਸਿਹਤ ਜਾਂ ਪੋਸ਼ਣ ਸਮੱਸਿਆਵਾਂ ਦਾ ਸ਼ੁਰੂਆਤੀ ਸੰਕੇਤ ਹੋ ਸਕਦੀ ਹੈ।",
    "rec.why.ai_explainability": "AI ਵਿਸ਼ਲੇਸ਼ਣ ਨੇ ਤਾਪਮਾਨ ਅਤੇ ਨਮੀ ਨੂੰ ਦੁੱਧ ਉਤਪਾਦਨ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਨ ਵਾਲੇ ਮੁੱਖ ਕਾਰਕ ਵਜੋਂ ਪਛਾਣਿਆ ਹੈ। ਕੂਲਿੰਗ ਸਹਾਇਤਾ ਵਾਤਾਵਰਣ ਤਣਾਅ ਨੂੰ ਘਟਾਏਗੀ।",
    "rec.why.warm_thi": "ਮੌਸਮ ਦੀ ਨਿਗਰਾਨੀ ਦਰਸਾਉਂਦੀ ਹੈ ਕਿ ਗਰਮੀ ਦੀਆਂ ਸਥਿਤੀਆਂ ਗਰਮੀ ਤਣਾਅ ਸੀਮਾ (THI {thi}) ਦੇ ਨੇੜੇ ਹਨ। ਵੱਧ ਜਲ ਸੰਤੁਲਨ ਨਿਗਰਾਨੀ ਦੁੱਧ ਘਟਣ ਤੋਂ ਰੋਕਣ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ।",
    "rec.why.moderate_thi": "ਮੌਸਮ ਨਿਗਰਾਨੀ ਦਰਮਿਆਨੀ ਗਰਮੀ ਤਣਾਅ (THI {thi}) ਦਰਸਾਉਂਦੀ ਹੈ। ਵਧਿਆ ਤਾਪਮਾਨ ਅਸੁਵਿਧਾ ਪੈਦਾ ਕਰਦਾ ਹੈ ਅਤੇ ਦੁੱਧ ਘਟਾ ਸਕਦਾ ਹੈ।",
    "rec.why.high_thi": "ਹਾਲੀਆ ਮੌਸਮ ਦੀਆਂ ਸਥਿਤੀਆਂ ਉੱਚ ਗਰਮੀ ਤਣਾਅ ({thi}) ਦਰਸਾਉਂਦੀਆਂ ਹਨ। ਗਰਮੀ ਤਣਾਅ ਖੁਰਾਕ ਘਟਾ ਸਕਦਾ ਹੈ, ਦੁੱਧ ਉਤਪਾਦਨ ਘਟਾ ਸਕਦਾ ਹੈ ਅਤੇ ਗਾਂ ਦੀ ਸਿਹਤ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰ ਸਕਦਾ ਹੈ।",
    "rec.why.fever_and_drop": "ਗਾਂ ਦੇ ਸਰੀਰ ਦਾ ਤਾਪਮਾਨ ਵਧਿਆ ਹੋਇਆ ਹੈ ({temp}) ਅਤੇ ਇਸਦਾ ਦੁੱਧ ਉਤਪਾਦਨ ਹਾਲੀਆ ਬੇਸਲਾਈਨ ਤੋਂ {drop} ਹੇਠਾਂ ਆ ਗਿਆ ਹੈ। ਇਹ ਲੱਛਣ ਸਿਹਤ ਸਮੱਸਿਆ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦੇ ਹਨ ਜਿਸਦੀ ਤੁਰੰਤ ਜਾਂਚ ਕੀਤੀ ਜਾਣੀ ਚਾਹੀਦੀ ਹੈ।",
    "rec.why.fever_alone": "ਗਾਂ ਦਾ ਦਰਜ ਸਰੀਰ ਦਾ ਤਾਪਮਾਨ ਆਮ ਸੀਮਾ ਤੋਂ ਵੱਧ ਹੈ ({temp})। ਇਹ ਬੁਖਾਰ ਜਾਂ ਗੰਭੀਰ ਲਾਗ ਦਾ ਸੰਕੇਤ ਹੋ ਸਕਦਾ ਹੈ ਅਤੇ ਪਸ਼ੂ ਡਾਕਟਰ ਦੁਆਰਾ ਤੁਰੰਤ ਜਾਂਚ ਕੀਤੀ ਜਾਣੀ ਚਾਹੀਦੀ ਹੈ।",
    "rec.why.milk_drop_significant": "ਦੁੱਧ ਉਤਪਾਦਨ ਵਿੱਚ ਕਾਫ਼ੀ ਗਿਰਾਵਟ ਆਈ ਹੈ (ਉਮੀਦ ਨਾਲੋਂ {drop} ਘੱਟ)। ਇਹ ਤਬਦੀਲੀ ਪੋਸ਼ਣ ਦੀ ਘਾਟ, ਸਿਹਤ ਸਮੱਸਿਆਵਾਂ ਜਾਂ ਵਾਤਾਵਰਣ ਤਣਾਅ ਨਾਲ ਜੁੜੀ ਹੋ ਸਕਦੀ ਹੈ।",
    "rec.why.milk_drop_moderate": "ਦੁੱਧ ਉਤਪਾਦਨ ਗਾਂ ਦੇ ਹਾਲੀਆ ਉਤਪਾਦਨ ਨਾਲੋਂ ਘੱਟ ਹੈ ({drop} ਗਿਰਾਵਟ)। ਖੁਰਾਕ ਵਿਵਸਥਿਤ ਕਰਨ ਨਾਲ ਦੁੱਧ ਸੁਧਾਰ ਵਿੱਚ ਮਦਦ ਮਿਲਦੀ ਹੈ।",
    "rec.why.abnormal_health": "ਤਾਜ਼ਾ ਨਿਰੀਖਣ ਦੌਰਾਨ ਗਾਂ ਵਿੱਚ ਅਸਧਾਰਨ ਸਿਹਤ ਸਥਿਤੀ ({condition}) ਦਰਜ ਕੀਤੀ ਗਈ ਸੀ। ਇਹ ਅਜਿਹੀ ਬਿਮਾਰੀ ਦਾ ਸੰਕੇਤ ਹੋ ਸਕਦਾ ਹੈ ਜੋ ਇਲਾਜ ਨਾ ਕੀਤੇ ਜਾਣ 'ਤੇ ਗਾਂ ਦੀ ਸਿਹਤ ਅਤੇ ਦੁੱਧ ਉਤਪਾਦਨ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰ ਸਕਦੀ ਹੈ।",
    "rec.why.fallback_vet": "ਹਾਲੀਆ ਨਿਗਰਾਨੀ ਦੌਰਾਨ ਗਾਂ ({cow}) ਵਿੱਚ ਅਸਧਾਰਨ ਸਿਹਤ ਜਾਂ ਵਧਿਆ ਤਾਪਮਾਨ ਦੇਖਿਆ ਗਿਆ। ਬਿਮਾਰੀ ਵਧਣ ਤੋਂ ਰੋਕਣ ਲਈ ਤੁਰੰਤ ਪਸ਼ੂ ਡਾਕਟਰ ਦੀ ਜਾਂਚ ਦੀ ਸਲਾਹ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ।",
    "rec.why.fallback_heat": "ਮੌਸਮ ਨਿਗਰਾਨੀ ਉੱਚ ਗਰਮੀ ਤਣਾਅ ਦਰਸਾਉਂਦੀ ਹੈ। ਕੂਲਿੰਗ ਸਹਾਇਤਾ ਤੋਂ ਬਿਨਾਂ ਖੁਰਾਕ ਅਤੇ ਦੁੱਧ ਉਤਪਾਦਨ ਘਟ ਸਕਦਾ ਹੈ।",
    "rec.why.fallback_feed": "{cow} ਦਾ ਦੁੱਧ ਜਾਂ ਖੁਰਾਕ ਆਮ ਪੱਧਰ ਤੋਂ ਘੱਟ ਗਿਆ। ਖੁਰਾਕ ਸੁਧਾਰ ਨਾਲ ਊਰਜਾ ਬਹਾਲੀ ਵਿੱਚ ਮਦਦ ਮਿਲਦੀ ਹੈ।",
    "rec.why.fallback_general": "ਆਟੋਮੇਟਿਡ ਨਿਗਰਾਨੀ ਨੇ {cow} ਲਈ ਧਿਆਨ ਦੇਣ ਯੋਗ ਕਾਰਕਾਂ ਦੀ ਪਛਾਣ ਕੀਤੀ ਹੈ।",
    "rec.toast.evaluated": "ਝੁੰਡ ਸਲਾਹਕਾਰ ਸਿਫਾਰਸ਼ਾਂ ਦਾ ਮੁਲਾਂਕਣ ਅਤੇ ਅੱਪਡੇਟ ਕੀਤਾ ਗਿਆ!",
    "rec.toast.eval_error": "ਸਿਫਾਰਸ਼ਾਂ ਦਾ ਮੁਲਾਂਕਣ ਕਰਨ ਵਿੱਚ ਅਸਮਰੱਥ।",
    "rec.toast.action_completed": "ਸਿਫਾਰਸ਼ ਕੀਤੀ ਕਾਰਵਾਈ ਨੂੰ ਪੂਰਾ ਚਿੰਨ੍ਹਿਤ ਕੀਤਾ ਗਿਆ।",
    "rec.toast.action_complete_error": "ਸਿਫਾਰਸ਼ ਨੂੰ ਪੂਰਾ ਚਿੰਨ੍ਹਿਤ ਕਰਨ ਵਿੱਚ ਅਸਮਰੱਥ।",
    "rec.toast.cow_completed": "ਗਾਂ ਲਈ ਸਾਰੀਆਂ ਸਿਫਾਰਸ਼ਾਂ ਪੂਰੀਆਂ ਚਿੰਨ੍ਹਿਤ ਕੀਤੀਆਂ ਗਈਆਂ।",
    "rec.toast.cow_complete_error": "ਸਾਰੀਆਂ ਸਿਫਾਰਸ਼ਾਂ ਨੂੰ ਪੂਰਾ ਚਿੰਨ੍ਹਿਤ ਕਰਨ ਵਿੱਚ ਅਸਮਰੱਥ।",
    "rec.toast.deleted": "ਸਿਫਾਰਸ਼ਾਂ ਸਫਲਤਾਪੂਰਵਕ ਮਿਟਾ ਦਿੱਤੀਆਂ ਗਈਆਂ।",
