    "sim.explain.feed_milk_neg": "{feed} ਕਿੱਲੋ ਚਾਰਾ ਵਧਾਉਣ ਨਾਲ ਰੋਜ਼ਾਨਾ ਚਾਰਾ ਲਾਗਤ ₹{feedCost} ਵਧਦੀ ਹੈ, ਪਰ ਮਾਡਲ ₹{price}/ਲਿਟਰ 'ਤੇ +₹{rev}/ਦਿਨ ਮੁੱਲ ਦੇ ਕੇਵਲ +{milk} ਲਿਟਰ/ਦਿਨ ਵਾਧੂ ਦੁੱਧ ਦੀ ਭਵਿੱਖਬਾਣੀ ਕਰਦਾ ਹੈ। ਵਾਧੂ ਚਾਰੇ ਦੀ ਲਾਗਤ ਦੁੱਧ ਦੇ ਮਾਲੀਏ ਨਾਲੋਂ ਵੱਧ ਹੈ, ਨਤੀਜੇ ਵਜੋਂ -₹{net}/ਦਿਨ ਦਾ ਅਨੁਮਾਨਿਤ ਸ਼ੁੱਧ ਨੁਕਸਾਨ ਹੁੰਦਾ ਹੈ।",
