    "sim.explain.feed_inc_milk_drop": "ਚਾਰਾ {feed} ਕਿੱਲੋ ਵਧਾਉਣ ਨਾਲ ਚਾਰੇ ਦੀ ਲਾਗਤ ਵਿੱਚ +₹{feedCost}/ਦਿਨ ਜੁੜਦੇ ਹਨ, ਪਰ ਅਨੁਮਾਨਿਤ ਦੁੱਧ ਉਤਪਾਦਨ {milk} ਲਿਟਰ/ਦਿਨ (-₹{rev} ਮਾਲੀਆ) ਘਟਦਾ ਹੈ। ਸੰਯੁਕਤ ਪ੍ਰਭਾਵ ਨਾਲ -₹{net}/ਦਿਨ ਦਾ ਅਨੁਮਾਨਿਤ ਨੁਕਸਾਨ ਹੁੰਦਾ ਹੈ।",
    "sim.explain.feed_inc_milk_same": "ਚਾਰਾ {feed} ਕਿੱਲੋ ਵਧਾਉਣ ਨਾਲ ਚਾਰੇ ਦੀ ਲਾਗਤ ਵਿੱਚ +₹{feedCost}/ਦਿਨ ਜੁੜਦੇ ਹਨ, ਜਦੋਂ ਕਿ ਅਨੁਮਾਨਿਤ ਦੁੱਧ ਉਤਪਾਦਨ ਵਿੱਚ ਕੋਈ ਬਦਲਾਅ ਨਹੀਂ ਹੁੰਦਾ (₹0.00 ਮਾਲੀਆ ਤਬਦੀਲੀ)। ਇਸ ਨਾਲ -₹{net}/ਦਿਨ ਦਾ ਰੋਜ਼ਾਨਾ ਖਰਚਾ ਹੁੰਦਾ ਹੈ।",
