    "sim.explain.feed_milk_pos": "{feed} કિગ્રા ખોરાક વધારવાથી દૈનિક ખોરાક ખર્ચ ₹{feedCost} વધે છે, પરંતુ અંદાજિત દૂધ ઉત્પાદન +{milk} લિટર/દિવસ વધે છે, જેથી +₹{rev} વધારાની આવક થાય છે. દૂધની આવક ખોરાકના ખર્ચ કરતાં વધુ હોવાથી +₹{net}/દિવસનો અંદાજિત ચોખ્ખો લાભ મળે છે.",
    "sim.explain.feed_milk_neg": "{feed} કિગ્રા ખોરાક ઉમેરવાથી દૈનિક ખોરાક ખર્ચ ₹{feedCost} વધે છે, પરંતુ મોડેલ ₹{price}/લિટર પર +₹{rev}/દિવસ કિંમતનું માત્ર +{milk} લિટર/દિવસ વધારાનું દૂધ દર્શાવે છે. વધારાનો ખોરાક ખર્ચ દૂધની આવક કરતાં વધી જતાં અંદાજિત ચોખ્ખો પ્રભાવ -₹{net}/દિવસ થાય છે.",
    "sim.explain.feed_milk_even": "{feed} કિગ્રા ખોરાક ઉમેરવાથી +₹{feedCost}/દિવસનો ખર્ચ થાય છે, જે અંદાજિત +{milk} લિટર/દિવસ દૂધની આવક (+₹{rev}/દિવસ) સાથે સંતુલિત રહે છે, જેના પરિણામે લગભગ બ્રેક-ઇવન અસર થાય છે.",
    "sim.explain.feed_inc_milk_drop": "ખોરાક {feed} કિગ્રા વધારવાથી ખોરાકના ખર્ચમાં +₹{feedCost}/દિવસ ઉમેરાય છે, પરંતુ અંદાજિત દૂધ ઉત્પાદન {milk} લિટર/દિવસ (-₹{rev} આવક) ઘટે છે. સંયુક્ત અસરમાં -₹{net}/દિવસનું અંદાજિત ચોખ્ખું નુકસાન થાય છે.",
    "sim.explain.feed_inc_milk_same": "ખોરાક {feed} કિગ્રા વધારવાથી ખોરાક ખર્ચમાં +₹{feedCost}/દિવસ ઉમેરાય છે, જ્યારે અંદાજિત દૂધ ઉત્પાદન યથાવત રહે છે (₹0.00 આવક ફેરફાર). આના પરિણામે -₹{net}/દિવસનો ચોખ્ખો દૈનિક ખર્ચ થાય છે.",
    "sim.explain.no_feed_milk_pos": "ખોરાક સેવનમાં કોઈ ફેરફાર ન હોવા છતાં (₹0.00 ખોરાક ખર્ચ તફાવત), પર્યાવરણીય અથવા કૂલિંગ ગોઠવણો અંદાજિત દૂધ ઉત્પાદનમાં +{milk} લિટર/દિવસનો વધારો કરે છે, જેથી +₹{net}/દિવસનો ચોખ્ખો નાણાકીય લાભ થાય છે.",
    "sim.explain.no_feed_milk_neg": "ખોરાક સેવન યથાવત હોવા છતાં (₹0.00 ખોરાક ખર્ચ તફાવત), પર્યાવરણીય તણાવ અંદાજિત દૂધ ઉત્પાદનમાં {milk} લિટર/દિવસનો ઘટાડો કરે છે, જેનાથી -₹{net}/દિવસનું અંદાજિત નુકસાન થાય છે.",
    "sim.explain.no_change": "ખોરાક સેવન અથવા અંદાજિત દૂધ ઉત્પાદનમાં કોઈ ફેરફાર ન હોવાથી ₹0.00 ચોખ્ખો નાણાકીય પ્રભાવ રહે છે.",
    "sim.explain.feed_dec_milk_pos": "ખોરાક {feed} કિગ્રા ઘટાડવાથી ખોરાકના ખર્ચમાં ₹{feedCost}/દિવસની બચત થાય છે જ્યારે અંદાજિત દૂધ ઉત્પાદનમાં +{milk} લિટર/દિવસ (+₹{rev}/દિવસ આવક) નો ફેરફાર થાય છે, જેથી +₹{net}/દિવસનો ચોખ્ખો નાણાકીય લાભ મળે છે.",
    "sim.explain.feed_dec_milk_neg_save": "ખોરાક {feed} કિગ્રા ઘટાડવાથી ખોરાકના ખર્ચમાં ₹{feedCost}/દિવસની બચત થાય છે, જે દૂધ ઉત્પાદનમાં {milk} લિટર/દિવસના ઘટાડાથી થયેલા નુકસાન (-₹{rev}/દિવસ) કરતાં વધુ છે, જેનાથી +₹{net}/દિવસની ચોખ્ખી બચત થાય છે.",
