    "rec.filter.all_statuses": "ಎಲ್ಲಾ ಸ್ಥಿತಿಗಳು",
    "rec.filter.pending_only": "ಬಾಕಿ ಇರುವವು ಮಾತ್ರ",
    "rec.filter.completed_only": "ಪೂರ್ಣಗೊಂಡವು ಮಾತ್ರ",
    "rec.filter.search_placeholder": "ಹಸುವಿನ ಹೆಸರು, ಕ್ರಮ ಅಥವಾ ವರ್ಗ ಹುಡುಕಿ...",
    "rec.modal.title": "ಏಕೀಕೃತ ಸಲಹಾ ಯೋಜನೆ ಮತ್ತು ಪುರಾವೆ ವಿಶ್ಲೇಷಣೆ",
    "rec.modal.overview_title": "ಏಕೀಕೃತ ಸಲಹಾ ಅವಲೋಕನ",
    "rec.modal.overview_body": "DairyVision AI ಯು {cow} ಗಾಗಿ {categories} ನಲ್ಲಿ {count} ಸಲಹಾ ಅಂಶಗಳನ್ನು ಸಂಯೋಜಿಸಿದೆ. ಎಲ್ಲಾ ಆರೋಗ್ಯ ವೀಕ್ಷಣೆಗಳು, ಉಷ್ಣ ಸೌಕರ್ಯ ಸೂಚ್ಯಂಕ ಮತ್ತು ಹಾಲು ಉತ್ಪಾದನಾ ಸಂಕೇತಗಳನ್ನು ಕೆಳಗೆ ಸಂರಕ್ಷಿಸಲಾಗಿದೆ.",
    "rec.modal.why_title": "ಈ ಶಿಫಾರಸು ಏಕೆ?",
