    "sim.explain.feed_milk_pos": "{feed} ಕೆಜಿ ಮೇವು ಸೇರಿಸುವುದರಿಂದ ದೈನಂದಿನ ಮೇವಿನ ವೆಚ್ಚ ₹{feedCost} ಹೆಚ್ಚಾಗುತ್ತದೆ, ಆದರೆ ಮುನ್ಸೂಚಿತ ಹಾಲು ಉತ್ಪಾದನೆ +{milk} ಲೀಟರ್/ದಿನ ಹೆಚ್ಚಾಗುತ್ತದೆ, ಇದು +₹{rev} ಹೆಚ್ಚುವರಿ ಆದಾಯವನ್ನು ತರುತ್ತದೆ. ಹಾಲಿನ ಆದಾಯವು ಮೇವಿನ ವೆಚ್ಚವನ್ನು ಮೀರುತ್ತದೆ, ಇದರಿಂದ +₹{net}/ದಿನ ಅಂದಾಜು ನಿವ್ವಳ ಲಾಭ ದೊರೆಯುತ್ತದೆ.",
    "sim.explain.feed_milk_neg": "{feed} ಕೆಜಿ ಮೇವು ಸೇರಿಸುವುದರಿಂದ ದೈನಂದಿನ ಮೇವಿನ ವೆಚ್ಚ ₹{feedCost} ಹೆಚ್ಚಾಗುತ್ತದೆ, ಆದರೆ ಮಾದರಿಯು ₹{price}/ಲೀಟರ್ ದರದಲ್ಲಿ +₹{rev}/ದಿನ ಮೌಲ್ಯದ ಕೇವಲ +{milk} ಲೀಟರ್/ದಿನ ಹೆಚ್ಚುವರಿ ಹಾಲನ್ನು ಊಹಿಸುತ್ತದೆ. ಹೆಚ್ಚುವರಿ ಮೇವಿನ ವೆಚ್ಚವು ಹಾಲಿನ ಆದಾಯಕ್ಕಿಂತ ಹೆಚ್ಚಾಗಿರುತ್ತದೆ, ಇದರಿಂದ -₹{net}/ದಿನ ಅಂದಾಜು ನಿವ್ವಳ ನಷ್ಟವಾಗುತ್ತದೆ.",
    "sim.explain.feed_milk_even": "{feed} ಕೆಜಿ ಮೇವು ಸೇರಿಸುವುದರಿಂದ +₹{feedCost}/ದಿನ ವೆಚ್ಚವಾಗುತ್ತದೆ, ಇದು ಮುನ್ಸೂಚಿತ +{milk} ಲೀಟರ್/ದಿನ ಹಾಲಿನ ಆದಾಯದೊಂದಿಗೆ (+₹{rev}/ದಿನ) ನಿಕಟವಾಗಿ ಸಮತೋಲನಗೊಳ್ಳುತ್ತದೆ, ಇದರಿಂದ ಸರಿಸುಮಾರು ಸಮತೋಲನ ಪ್ರಭಾವ ಉಂಟಾಗುತ್ತದೆ.",
    "sim.explain.feed_inc_milk_drop": "ಮೇವನ್ನು {feed} ಕೆಜಿ ಹೆಚ್ಚಿಸುವುದರಿಂದ ಮೇವಿನ ವೆಚ್ಚದಲ್ಲಿ +₹{feedCost}/ದಿನ ಹೆಚ್ಚಾಗುತ್ತದೆ, ಆದರೆ ಮುನ್ಸೂಚಿತ ಹಾಲು ಉತ್ಪಾದನೆಯು {milk} ಲೀಟರ್/ದಿನ (-₹{rev} ಆದಾಯ) ಕಡಿಮೆಯಾಗುತ್ತದೆ. ಸಂಯೋಜಿತ ಪರಿಣಾಮವು -₹{net}/ದಿನ ಅಂದಾಜು ನಿವ್ವಳ ನಷ್ಟವನ್ನು ಉಂಟುಮಾಡುತ್ತದೆ.",
    "sim.explain.feed_inc_milk_same": "ಮೇವನ್ನು {feed} ಕೆಜಿ ಹೆಚ್ಚಿಸುವುದರಿಂದ ಮೇವಿನ ವೆಚ್ಚದಲ್ಲಿ +₹{feedCost}/ದಿನ ಹೆಚ್ಚಾಗುತ್ತದೆ, ಆದರೆ ಮುನ್ಸೂಚಿತ ಹಾಲು ಉತ್ಪಾದನೆ ಬದಲಾಗದೆ ಉಳಿಯುತ್ತದೆ (₹0.00 ಆದಾಯ ಬದಲಾವಣೆ). ಇದು -₹{net}/ದಿನ ನಿವ್ವಳ ದೈನಂದಿನ ವೆಚ್ಚಕ್ಕೆ ಕಾರಣವಾಗುತ್ತದೆ.",
    "sim.explain.no_feed_milk_pos": "ಮೇವು ಸೇವನೆಯಲ್ಲಿ ಯಾವುದೇ ಬದಲಾವಣೆಯಿಲ್ಲದೆ (₹0.00 ಮೇವಿನ ವೆಚ್ಚ ವ್ಯತ್ಯಾಸ), ಪರಿಸರ ಅಥವಾ ಕೂಲಿಂಗ್ ಹೊಂದಾಣಿಕೆಗಳು ಮುನ್ಸೂಚಿತ ಹಾಲು ಉತ್ಪಾದನೆಯನ್ನು +{milk} ಲೀಟರ್/ದಿನ ಹೆಚ್ಚಿಸುತ್ತವೆ, ಇದರಿಂದ +₹{net}/ದಿನ ನಿವ್ವಳ ಆರ್ಥಿಕ ಲಾಭ ದೊರೆಯುತ್ತದೆ.",
    "sim.explain.no_feed_milk_neg": "ಮೇವು ಸೇವನೆಯಲ್ಲಿ ಯಾವುದೇ ಬದಲಾವಣೆಯಿಲ್ಲದೆ (₹0.00 ಮೇವಿನ ವೆಚ್ಚ ವ್ಯತ್ಯಾಸ), ಪರಿಸರದ ಒತ್ತಡವು ಮುನ್ಸೂಚಿತ ಹಾಲು ಉತ್ಪಾದನೆಯನ್ನು {milk} ಲೀಟರ್/ದಿನ ಕಡಿಮೆ ಮಾಡುತ್ತದೆ, ಇದರಿಂದ -₹{net}/ದಿನ ಅಂದಾಜು ಆದಾಯ ನಷ್ಟವಾಗುತ್ತದೆ.",
    "sim.explain.no_change": "ಮೇವು ಸೇವನೆ ಅಥವಾ ಮುನ್ಸೂಚಿತ ಹಾಲು ಉತ್ಪಾದನೆಯಲ್ಲಿ ಯಾವುದೇ ಬದಲಾವಣೆಯಿಲ್ಲದಿರುವುದು ₹0.00 ನಿವ್ವಳ ಆರ್ಥಿಕ ಪ್ರಭಾವಕ್ಕೆ ಕಾರಣವಾಗುತ್ತದೆ.",
    "sim.explain.feed_dec_milk_pos": "ಮೇವನ್ನು {feed} ಕೆಜಿ ಕಡಿಮೆ ಮಾಡುವುದರಿಂದ ಮೇವಿನ ವೆಚ್ಚದಲ್ಲಿ ₹{feedCost}/ದಿನ ಉಳಿತಾಯವಾಗುತ್ತದೆ ಮತ್ತು ಮುನ್ಸೂಚಿತ ಹಾಲು ಉತ್ಪಾದನೆಯು +{milk} ಲೀಟರ್/ದಿನ ಬದಲಾಗುತ್ತದೆ (+₹{rev}/ದಿನ ಆದಾಯ), ಇದರಿಂದ +₹{net}/ದಿನ ನಿವ್ವಳ ಆರ್ಥಿಕ ಲಾಭ ದೊರೆಯುತ್ತದೆ.",
    "sim.explain.feed_dec_milk_neg_save": "ಮೇವನ್ನು {feed} ಕೆಜಿ ಕಡಿಮೆ ಮಾಡುವುದರಿಂದ ಮೇವಿನ ವೆಚ್ಚದಲ್ಲಿ ₹{feedCost}/ದಿನ ಉಳಿತಾಯವಾಗುತ್ತದೆ, ಇದು ಹಾಲು ಉತ್ಪಾದನೆಯಲ್ಲಿ {milk} ಲೀಟರ್/ದಿನ ಕುಸಿತದಿಂದ ಉಂಟಾದ ಆದಾಯ ನಷ್ಟಕ್ಕಿಂತ (-₹{rev}/ದಿನ) ಹೆಚ್ಚಾಗಿರುತ್ತದೆ, ಇದರಿಂದ +₹{net}/ದಿನ ನಿವ್ವಳ ಉಳಿತಾಯವಾಗುತ್ತದೆ.",
    "sim.explain.feed_dec_milk_neg_loss": "ಮೇವನ್ನು {feed} ಕೆಜಿ ಕಡಿಮೆ ಮಾಡುವುದರಿಂದ ಮೇವಿನ ವೆಚ್ಚದಲ್ಲಿ ₹{feedCost}/ದಿನ ಉಳಿತಾಯವಾಗುತ್ತದೆ, ಆದರೆ ಹಾಲು ಉತ್ಪಾದನೆಯು {milk} ಲೀಟರ್/ದಿನ (-₹{rev}/ದಿನ ಆದಾಯ) ಕುಸಿಯುತ್ತದೆ, ಇದರಿಂದ -₹{net}/ದಿನ ಅಂದಾಜು ನಿವ್ವಳ ನಷ್ಟ ಉಂಟಾಗುತ್ತದೆ.",
